templates.template:
enemy ${Name} {
	sprite "Enemy/Tumbleweed.png"
	points 10
	on pop: split into 2
	on contact: damage 1
}

enemy ${Name} {
	sprite "Enemy/Bomb.png"
	points 25
	on pop: split into 8 ${fragmentType:CrossReference('Split.fragmentType')}
	on contact: damage 2
}

powerup ${Name} {
	sprite "Powerup/Shield.png"
	gives: shield for 8 s
}

player ${Name} {
	health 3 max 5
	speed 5
	tongue 0.8 s
	cooldown 1 s
}

mode ${Name} "${Title}" {
	description "Pop everything to win."
	player ${profile:CrossReference('GameMode.player')}
	arena {
		background "Desert"
	}
	layout {
		${type:CrossReference('EnemySpawn.type')} size 3 at (50%, 70%)
	}
	win when all enemies cleared
	lose when health depleted
}

mode ${Name} "${Title}" {
	description "Survive as long as you can."
	player ${profile:CrossReference('GameMode.player')}
	arena {
		background "Desert"
	}
	waves looping escalate by 1 {
		wave {
			${type:CrossReference('EnemySpawn.type')} size 3 at (50%, 75%)
		}
	}
	lose when health depleted or 20 enemies alive
}

wave after 2 s {
	2 * ${type:CrossReference('EnemySpawn.type')} size 3 at (50%, 75%) moving ${direction:Enum('Direction')}
}

mode ${Name} "${Title}" {
	description "Clear every level."
	player ${profile:CrossReference('GameMode.player')}
	level "${First}" {
		arena {
			background "Desert"
		}
		layout {
			${type:CrossReference('EnemySpawn.type')} size 2 at (60%, 50%) moving left
		}
	}
	level "${Second}" {
		arena {
			background "Desert"
		}
		layout {
			${type} size 3 at (60%, 50%) moving left
		}
	}
	win when all enemies cleared
	lose when health depleted
}

level "${Title}" {
	arena {
		background "Desert"
	}
	layout {
		${type:CrossReference('EnemySpawn.type')} size 3 at (60%, 50%) moving left
	}
}
